// The "Run the demo" trigger lands here. Two invented cards — one with a phone number
// and one without — so pressing Execute shows both paths through the workflow without
// a Trello webhook, a Twilio account or a single credential. The shapes are exactly
// what Trello posts on a real card update, which is the point: the reader below never
// knows the difference.

const now = new Date().toISOString();

return [
  {
    json: {
      action: 'createCard',
      'idAction': '680a00000000000001',
      data: {
        card: {
          id:           '680a00000000000001',
          name:         'Jane Smith — Quote request',
          desc:         'Customer: Jane Smith\nPhone: +1 555-0123\nEmail: jane@example.com\nCompany: Acme Co\nBudget: $5,000\nTimeline: ASAP\n\nNeed a quote for marketing automation.',
          shortLink:    'abc123',
          idList:       '680a00000000000010',
          idLabels:     [],
          labels:       [{ name: 'lead', color: 'green' }, { name: 'quote', color: 'purple' }],
          pos:          16384,
          idMembers:    [],
          creation:     now
        },
        list:  { id: '680a00000000000010', name: 'New Leads' },
        board: { id: '680a00000000000000', name: 'Workfluxa Leads' }
      },
      memberCreator: { id: '680a000000000000ff', username: 'board-member', fullName: 'Sam' },
      'date': now
    }
  },
  {
    json: {
      action: 'createCard',
      'idAction': '680a00000000000002',
      data: {
        card: {
          id:       '680a00000000000002',
          name:     'Enquiry — no phone on card',
          desc:     'Customer: Robert Chen\nEmail: rob@example.com\nCompany: Beta Ltd\n\nGeneral enquiry about services.',
          shortLink: 'def456',
          idList:   '680a00000000000010',
          idLabels: [],
          labels:   [{ name: 'lead', color: 'green' }],
          pos:      32768,
          idMembers: [],
          creation: now
        },
        list:  { id: '680a00000000000010', name: 'New Leads' },
        board: { id: '680a00000000000000', name: 'Workfluxa Leads' }
      },
      memberCreator: { id: '680a000000000000ff', username: 'board-member', fullName: 'Sam' },
      'date': now
    }
  }
];

// TRELLO-SMS — CONFIG
// Everything you might want to change lives in this one node. Nothing else in the
// workflow needs editing.
//
// A blank key means that step is SKIPPED, never that the run fails. That is what lets
// this be demonstrated on a screen-share before a single Trello or Twilio credential
// exists — the SMS is built in full and shown, never sent.
//
// The same config node ships in every n8n workflow in this project. It is the document
// a non-developer edits, and the reason these templates run on n8n Cloud with zero
// host environment variables.

// -------------------------------------------------------- Trello
// The board and list to watch. The ids live in the Trello URL:
//   trello.com/b/<board-id>/<board-name>
//   trello.com/b/<board-id>/<board-name>/<list-name>-<list-id>
const TRELLO_KEY    = '';
const TRELLO_TOKEN  = '';
const TRELLO_BOARD_ID = '';
const TRELLO_LIST_ID  = '';

// -------------------------------------------------------- Twilio
// Account sid, auth token and the Twilio phone number that sends. Get them from
// twilio.com/console. Both blank -> the SMS is built and shown, never sent.
const TWILIO_ACCOUNT_SID = '';
const TWILIO_AUTH_TOKEN  = '';
const TWILIO_FROM_NUMBER = '+14155238886';

// Where test SMS lands when DRY_RUN is true and you want to see a real message.
const TRENCH_PHONE = '';

// -------------------------------------------------------- SMS content
// Template for the outbound SMS. {{field}} placeholders: contact_name, card_name,
// company, budget, timeline, url.
const SMS_TEMPLATE = (
  "Hi {{contact_name}}, we received your request \"{{card_name}}\" " +
  "and a member of the team will follow up within 1 business hour. — {{company}}"
);

// -------------------------------------------------------- Safety switch
//   DRY_RUN true  (how it ships) -> nothing is sent. The SMS is built and shown in
//                                   STOP: preview — SMS not sent.
//   DRY_RUN false                -> Twilio sends for real. Needs TWILIO_ACCOUNT_SID
//                                   + TWILIO_AUTH_TOKEN, and a real phone number on the card.
const DRY_RUN = true;

const MODE = DRY_RUN !== true ? 'live' : 'preview';

// -------------------------------------------------------- What counts as routable
// A card must carry at least one of these custom-field names for a phone number. Trello
// custom fields arrive on action.data.card.customFieldItems; this is the list of field
// ids (long hex strings) to look for. Leave empty to scan the card description text.
const PHONE_FIELD_IDS = [];

// A prefix that marks a card as a lead. Leave empty to match all cards on the watched
// list. (This is the rule-table concept from ghl-lead-intake-router — one setting, no code.)
const LEAD_LABEL_PREFIX = 'lead';

const SETTINGS = {
  trello_key:           TRELLO_KEY.trim(),
  trello_token:         TRELLO_TOKEN.trim(),
  trello_board_id:      TRELLO_BOARD_ID.trim(),
  trello_list_id:       TRELLO_LIST_ID.trim(),

  twilio_account_sid:   TWILIO_ACCOUNT_SID.trim(),
  twilio_auth_token:    TWILIO_AUTH_TOKEN.trim(),
  twilio_from_number:   TWILIO_FROM_NUMBER.trim(),
  trench_phone:         TRENCH_PHONE.trim(),

  sms_template:         SMS_TEMPLATE,

  phone_field_ids:   PHONE_FIELD_IDS,
  lead_label_prefix: LEAD_LABEL_PREFIX.trim(),

  mode:        MODE,
  dry_run:     MODE !== 'live',
  twilio_enabled: MODE === 'live'
    && TWILIO_ACCOUNT_SID.trim() !== ''
    && TWILIO_AUTH_TOKEN.trim() !== ''
};

// config passes the incoming payload through untouched under `lead`, so whichever trigger
// fired the next node reads the payload from the same place. It runs once per incoming item.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((card) => ({ json: Object.assign({}, SETTINGS, { lead: card }) }));

// One card out of whatever Trello posted. The payload may arrive as a raw Trello
// webhook, a form POST forwarded into n8n, or the demo cards above — this reader
// handles all three shapes and pulls the same facts out of each.
//
// Output per card: the extracted lead fields, `_ok` and `_problems`.

const cfg = $('config').first().json;
const T = (v) => String(v == null ? '' : v).trim();
const NAME_RE  = /^([A-Z][a-z]+(?:\s[A-Z][a-z]+)+)$/;
const PHONE_RE = /^\+?[0-9][0-9\s().-]{6,15}$/;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

// Flatten a Trello webhook payload (action.data.card etc.) or a bare card object
// into something we can scan with simple string lookups.
function flatten(obj, depth, out) {
  out = out || {};
  if (!obj || typeof obj !== 'object' || depth > 4) return out;
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (v && typeof v === 'object' && !Array.isArray(v)) flatten(v, depth + 1, out);
    else out[String(k).toLowerCase()] = Array.isArray(v) ? v.join(', ') : v;
  }
  return out;
}

function extractCard(json) {
  const j = json;
  if (j.action && j.data && j.data.card) return { raw: j.data.card, action: j.action, wrapper: j };
  if (j.data && j.data.card) return { raw: j.data.card, action: j.action || { type: 'unknown' }, wrapper: j };
  if (j.card) return { raw: j.card, action: { type: 'direct' }, wrapper: j };
  if (j.name) return { raw: j, action: { type: 'direct' }, wrapper: j };
  return { raw: {}, action: { type: 'unknown' }, wrapper: j };
}

function readOne(json) {
  const { raw, action } = extractCard(json);
  const f = flatten(raw, 0);

  // The human-entered text on the card — desc and name only. The flat fields contain
  // Trello system ids (long digit strings) that would look like phone numbers.
  const descText = T(raw.desc || f.desc || f.description || '') + ' ' + T(raw.name || f.name || '');

  // Pull phone: custom fields first, then named fields, then the description text only
  let phone = '';
  if (raw.customFieldItems && cfg.phone_field_ids && cfg.phone_field_ids.length) {
    for (const item of raw.customFieldItems) {
      if (cfg.phone_field_ids.indexOf(item.id) >= 0 && item.value && item.value.text) {
        phone = T(item.value.text);
        break;
      }
    }
  }
  if (!phone) {
    phone = T(f.phone || f.phonenumber || f.phonecontact || f['phone-number']);
  }
  if (!phone) {
    // Scan only the description and card name — not the entire payload, which
    // contains Trello system ids (long digit strings) that look like phone numbers.
    const descText = T(raw.desc || f.desc || f.description || '') + ' ' + T(raw.name || f.name || '');
    const phoneMatch = descText.match(/\+?\d{1,4}[\s.()\-]?\d{2,4}[\s.()\-]?\d{3,4}([\s.()\-]?\d{3,4})?/g);
    phone = phoneMatch ? phoneMatch[0].trim() : '';
  }

  // Name: try labels, desc, or field names
  let name = '';
  if (raw.labels && raw.labels.length) {
    for (const label of raw.labels) {
      if (label.name && NAME_RE.test(label.name)) { name = T(label.name); break; }
    }
  }
  if (!name) {
    name = T(f.name || f.customer || f.contactname || f.contact);
    const m = descText.match(/Customer:\s*([A-Z][a-z]+(?:\s[A-Z][a-z]+)+)/i);
    if (m) name = T(m[1]);
  }

  // Email, company, budget, timeline from the description text
  const email = T(f.email || (function() {
    const m = descText.match(/Email:\s*([^\s@]+@[^\s@]+\.[^\s@]{2,})/i);
    return m ? m[1] : '';
  })());

  const company = T(f.company || (function() {
    const m = descText.match(/Company:\s*([^\n]+)/i);
    return m ? m[1] : '';
  })());

  const budget = T((function() {
    const m = descText.match(/Budget:\s*([^\n]+)/i);
    return m ? m[1] : '';
  })());

  const timeline = T((function() {
    const m = descText.match(/Timeline:\s*([^\n]+)/i);
    return m ? m[1] : '';
  })());

  const cardName = T(raw.name || f.title || f.summary || f.subject || '');
  const cardUrl  = 'https://trello.com/c/' + (raw.shortLink || 'x') + '/' + (raw.idShort || '');

  const labels = (raw.labels || []).map((l) => T(l.name || l)).filter(Boolean);
  const isLead = !cfg.lead_label_prefix || labels.some((l) => l.toLowerCase().startsWith(cfg.lead_label_prefix.toLowerCase()));

  const problems = [];
  if (!phone)            problems.push('no phone number — cannot send SMS');
  if (!name && !company) problems.push('no name or company to personalise the message with');
  if (!isLead)           problems.push('card does not carry a lead label (' + (cfg.lead_label_prefix || 'lead') + ')');

  const summary = [
    'Card on "' + (f.boardname || (raw.board && raw.board.name) || 'Trello') + '"',
    'list "' + (f.listname || (raw.list && raw.list.name) || 'unknown') + '"',
    name ? 'for ' + name : '',
    phone ? '— has a number' : '— NO number to SMS'
  ].filter(Boolean).join(' ');

  return {
    _ok:         problems.length === 0,
    _problems:   problems,
    _card_id:    T(raw.id || f.id || ''),
    card_name:   cardName,
    card_url:    cardUrl,
    action_type: T(action.type || ''),
    contact_name: name,
    company:     company,
    phone:       phone,
    email:       email,
    budget:      budget,
    timeline:    timeline,
    labels:      labels,
    summary:     summary,
    received:    new Date().toISOString()
  };
}

return $input.all().map((item) => ({ json: readOne(item.json) }));

// A card this workflow cannot use — no phone number to SMS, or no lead label, etc.
// It is dropped here rather than sent into a Twilio call that would fail, but the
// reason is kept so the execution list says why the card was not texted.
return $input.all().map((i) => ({
  json: {
    _outcome: 'rejected',
    _reason:  (i.json._problems || []).join('; ') || 'card could not be read',
    card_url: i.json.card_url,
    summary:  i.json.summary
  }
}));

// Build the SMS body from the template in config and the card fields. This node runs
// whether or not Twilio is configured — the message is constructed the same way either
// way, so the preview shows exactly what would be sent.

const cfg = $('config').first().json;
const lead = $json;

// Simple {{key}} substitution. Unknown keys are left as-is so the gap is visible.
function render(tpl, fields) {
  return tpl.replace(/\{\{(\w+)\}\}/g, (m, key) => {
    const v = fields[key];
    return (v !== undefined && v !== null && v !== '') ? String(v) : m;
  });
}

const fields = {
  contact_name:  lead.contact_name || 'there',
  card_name:     lead.card_name || '',
  company:       lead.company || '',
  budget:        lead.budget || '',
  timeline:      lead.timeline || '',
  url:           lead.card_url || '',
  phone:         lead.phone || ''
};

const body = render(cfg.sms_template, fields);

// In DRY_RUN mode and a trench phone is set, that is WHERE the SMS would go — so the
// operator can see a real message land on their own device. Otherwise the body is shown
// on the STOP node.
const to = (cfg.dry_run && cfg.trench_phone) ? cfg.trench_phone : (lead.phone || '');

return [{
  json: {
    _sms_to: to,
    _sms_body: body,
    _sms_from: cfg.twilio_from_number,
    contact_name: lead.contact_name,
    card_name: lead.card_name,
    phone: lead.phone,
    company: lead.company,
    summary: lead.summary
  }
}];

// DRY_RUN is still true, or the Twilio credentials are blank. Nothing was sent — and
// this node's output IS the result: the exact SMS body that would have gone out, and
// to which number. Open it to read what Twilio would receive.
return $input.all().map((i) => ({
  json: {
    _outcome: 'preview — nothing sent',
    _reason:  'Twilio not written: DRY_RUN is true or the account sid / auth token is blank',
    card_url: i.json.card_url || i.json.card_url,
    to:       i.json._sms_to,
    from:     i.json._sms_from,
    body:     i.json._sms_body,
    summary:  i.json.summary
  }
}));

// The SMS was accepted by Twilio. This node's output is the record: the card, the
// number it went to, and the Twilio message id.
return $input.all().map((i) => ({
  json: {
    _outcome: 'sent',
    card_url: i.json.card_url || i.json.card_url,
    to:       i.json.to || i.json._sms_to,
    sid:      i.json.sid || '(no sid returned)',
    body:     i.json.body || i.json._sms_body,
    cost_usd: (i.json.price && i.json.price.hasOwnProperty('amount')) ? i.json.price.amount : null,
    summary:  i.json.summary
  }
}));

// Twilio refused the send (invalid number, auth failure, etc.). The response body is
// on this node so the operator can see why, not just that it failed.
return $input.all().map((i) => ({
  json: {
    _outcome: 'failed',
    _reason:  i.json.error || 'Twilio rejected the send',
    card_url: i.json.card_url || i.json.card_url,
    to:       i.json.to || i.json._sms_to,
    body:     i.json._sms_body,
    summary:  i.json.summary
  }
}));
